/** Routes tagged `sign · templates`. */
export class SignTemplatesResource extends Resource {
  /**
   * Arquiva um modelo.
   *
   * Arquivado não muda nem gera documento, e libera o nome. Os envelopes que
   * ele já gerou não mudam. Exige `sign.manage`.
   *
   * `POST /v1/sign/templates/{id}/archive`
   *
   * @param id ID do modelo (Snowflake)
   * @param options Per-call overrides.
   */
  archiveSignTemplate(id: string, options?: RequestOptions): Promise<S.SignTemplateDto> {
    return this._http.request({ method: 'POST', path: `/v1/sign/templates/${seg(id)}/archive`, options });
  }

  /**
   * Cria um modelo de documento.
   *
   * Toda lacuna `{{chave}}` do título e do texto precisa de campo, e todo
   * campo precisa de lugar. O modelo volta normalizado: o que a tela mostra é
   * o que vai ao documento. Exige `sign.manage`.
   *
   * `POST /v1/sign/templates`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createSignTemplate(body: S.SignTemplateBody, options?: RequestOptions): Promise<S.SignTemplateDto> {
    return this._http.request({ method: 'POST', path: `/v1/sign/templates`, body, options });
  }

  /**
   * Abre um modelo, arquivado ou não.
   *
   * Devolve a versão atual com os campos e o PDF de base. Modelo de outra
   * organização responde como inexistente.
   *
   * `GET /v1/sign/templates/{id}`
   *
   * @param id ID do modelo (Snowflake)
   * @param options Per-call overrides.
   */
  getSignTemplate(id: string, options?: RequestOptions): Promise<S.SignTemplateDto> {
    return this._http.request({ method: 'GET', path: `/v1/sign/templates/${seg(id)}`, options });
  }

  /**
   * Lista os modelos de documento da organização, por cursor.
   *
   * Os arquivados só vêm com `archived=true`. Exige `sign.send`: quem envia
   * escolhe o modelo.
   *
   * `GET /v1/sign/templates`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listSignTemplates(query?: SignTemplatesListSignTemplatesQuery, options?: RequestOptions): Promise<S.SignTemplatesPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/sign/templates`, query, options });
  }

  /**
   * Iterates every item of `listSignTemplates`, following `next_page_token` page after page.
   *
   * `GET /v1/sign/templates`
   */
  listSignTemplatesAll(query?: SignTemplatesListSignTemplatesQuery, options?: RequestOptions): Paginator<NonNullable<S.SignTemplatesPageDto["templates"]>[number], S.SignTemplatesPageDto> {
    return new Paginator((page_token) => this.listSignTemplates({ ...query, page_token } as SignTemplatesListSignTemplatesQuery, options), "templates", query?.page_token ?? undefined);
  }

  /**
   * O PDF que um modelo gera, sem gravar nada.
   *
   * Lacuna sem valor aparece como `[rótulo]`. Com os mesmos valores, as
   * mesmas pessoas e no mesmo dia, os bytes são os do envelope.
   *
   * `POST /v1/sign/templates/{id}/preview`
   *
   * @param id ID do modelo (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  previewSignTemplate(id: string, body: S.SignTemplatePreviewBody, options?: RequestOptions): Promise<Response> {
    return this._http.request({ method: 'POST', path: `/v1/sign/templates/${seg(id)}/preview`, body, responseType: 'raw', options });
  }

  /**
   * O PDF do modelo que está no editor, sem gravar.
   *
   * Confere o modelo como a gravação confere: o que passa aqui grava. Exige
   * `sign.manage`.
   *
   * `POST /v1/sign/templates/preview`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  previewSignTemplateDraft(body: S.SignTemplateDraftPreviewBody, options?: RequestOptions): Promise<Response> {
    return this._http.request({ method: 'POST', path: `/v1/sign/templates/preview`, body, responseType: 'raw', options });
  }

  /**
   * Grava a versão nova de um modelo.
   *
   * A versão anterior fica no histórico: os envelopes que ela gerou continuam
   * apontando para o texto exato de que saíram. Exige `sign.manage`.
   *
   * `PUT /v1/sign/templates/{id}`
   *
   * @param id ID do modelo (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateSignTemplate(id: string, body: S.SignTemplateUpdateBody, options?: RequestOptions): Promise<S.SignTemplateDto> {
    return this._http.request({ method: 'PUT', path: `/v1/sign/templates/${seg(id)}`, body, options });
  }
}

