/** Routes tagged `sign · vaults`. */
export class SignVaultsResource extends Resource {
  /**
   * Cria um cofre de envelopes.
   *
   * Com `require_mfa`, o código do autenticador vem junto: prova que quem
   * liga o segundo fator tem o autenticador, e a resposta já traz a abertura.
   *
   * `POST /v1/sign/vaults`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createSignVault(body: S.SignVaultBody, options?: RequestOptions): Promise<S.SignVaultSavedDto> {
    return this._http.request({ method: 'POST', path: `/v1/sign/vaults`, body, options });
  }

  /**
   * Apaga um documento importado.
   *
   * Só quem administra o cofre apaga; sai também o arquivo do Files.
   *
   * `DELETE /v1/sign/imports/{id}`
   *
   * @param id ID do documento importado (Snowflake)
   * @param options Per-call overrides.
   */
  deleteSignImport(id: string, options?: RequestOptions): Promise<void> {
    return this._http.request({ method: 'DELETE', path: `/v1/sign/imports/${seg(id)}`, responseType: 'void', options });
  }

  /**
   * Apaga um cofre vazio.
   *
   * Só administrador apaga; o cofre padrão e cofre com envelope são recusados
   * (`sign_vault_default`, `sign_vault_not_empty`).
   *
   * `DELETE /v1/sign/vaults/{id}`
   *
   * @param id ID do cofre (Snowflake)
   * @param options Per-call overrides.
   */
  deleteSignVault(id: string, options?: RequestOptions): Promise<void> {
    return this._http.request({ method: 'DELETE', path: `/v1/sign/vaults/${seg(id)}`, responseType: 'void', options });
  }

  /**
   * Baixa o PDF de um documento importado.
   *
   * O serviço confere o SHA-256 da entrada antes do primeiro byte, e o
   * download fica na trilha de auditoria.
   *
   * `GET /v1/sign/imports/{id}/document`
   *
   * @param id ID do documento importado (Snowflake)
   * @param options Per-call overrides.
   */
  downloadSignImport(id: string, options?: RequestOptions): Promise<Response> {
    return this._http.request({ method: 'GET', path: `/v1/sign/imports/${seg(id)}/document`, responseType: 'raw', options });
  }

  /**
   * Abre um documento importado.
   *
   * O que foi declarado na entrada (título, partes, data, observação) e o
   * SHA-256 do arquivo. Exige `sign.read` e a pessoa na lista do cofre; cofre
   * com código do autenticador pede o cofre aberto.
   *
   * `GET /v1/sign/imports/{id}`
   *
   * @param id ID do documento importado (Snowflake)
   * @param options Per-call overrides.
   */
  getSignImport(id: string, options?: RequestOptions): Promise<S.SignImportDto> {
    return this._http.request({ method: 'GET', path: `/v1/sign/imports/${seg(id)}`, options });
  }

  /**
   * Abre o cadastro de um cofre.
   *
   * Traz a lista de acesso com o nome de cada sujeito e o histórico do cofre.
   * Cofre com segundo fator trancado responde `412 sign_vault_locked`.
   *
   * `GET /v1/sign/vaults/{id}`
   *
   * @param id ID do cofre (Snowflake)
   * @param options Per-call overrides.
   */
  getSignVault(id: string, options?: RequestOptions): Promise<S.SignVaultDetailDto> {
    return this._http.request({ method: 'GET', path: `/v1/sign/vaults/${seg(id)}`, options });
  }

  /**
   * Guarda num cofre um contrato já assinado fora da plataforma (multipart: `meta` e `file`).
   *
   * Serve ao papel escaneado e ao PDF assinado em outra ferramenta. Não vira
   * envelope: não tem signatário, cadeia nem selo. O PDF passa pelo antivírus
   * e o SHA-256 dele fica gravado; todo download confere o arquivo contra ele.
   * O mesmo arquivo entra uma vez por organização. Pede poder criar no cofre
   * (editor, ou o público `organization` para quem só vê o que cria).
   *
   * `POST /v1/sign/imports`
   *
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `Idempotency-Key`.
   */
  importSignDocument(body?: FormData, options?: RequestOptions & { headers?: { "Idempotency-Key"?: string } }): Promise<S.SignImportDto> {
    return this._http.request({ method: 'POST', path: `/v1/sign/imports`, body, bodyType: 'multipart', options });
  }

  /**
   * Lista os documentos importados dos cofres que a pessoa vê, por cursor.
   *
   * Nos cofres em que a pessoa vê só o que criou, entram só os que ela
   * importou. Repita com `page_token = next_page_token` até ele voltar vazio.
   *
   * `GET /v1/sign/imports`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listSignImports(query?: SignVaultsListSignImportsQuery, options?: RequestOptions): Promise<S.SignImportsPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/sign/imports`, query, options });
  }

  /**
   * Iterates every item of `listSignImports`, following `next_page_token` page after page.
   *
   * `GET /v1/sign/imports`
   */
  listSignImportsAll(query?: SignVaultsListSignImportsQuery, options?: RequestOptions): Paginator<NonNullable<S.SignImportsPageDto["imports"]>[number], S.SignImportsPageDto> {
    return new Paginator((page_token) => this.listSignImports({ ...query, page_token } as SignVaultsListSignImportsQuery, options), "imports", query?.page_token ?? undefined);
  }

  /**
   * Os cofres de envelopes que a pessoa vê.
   *
   * O cofre padrão ("Contratos") nasce no primeiro uso. Cofre com segundo
   * fator sem abertura em vigor vem com `locked`; cofre de público `members`
   * em que a pessoa não está não vem.
   *
   * `GET /v1/sign/vaults`
   *
   * @param options Per-call overrides.
   */
  listSignVaults(options?: RequestOptions): Promise<S.SignVaultsDto> {
    return this._http.request({ method: 'GET', path: `/v1/sign/vaults`, options });
  }

  /**
   * Tranca de novo um cofre aberto.
   *
   * Encerra a abertura da pessoa naquele cofre antes dos 15 minutos; o
   * bilhete segue valendo para os outros cofres abertos com ele.
   *
   * `POST /v1/sign/vaults/{id}/lock`
   *
   * @param id ID do cofre (Snowflake)
   * @param options Per-call overrides.
   */
  lockSignVault(id: string, options?: RequestOptions): Promise<void> {
    return this._http.request({ method: 'POST', path: `/v1/sign/vaults/${seg(id)}/lock`, responseType: 'void', options });
  }

  /**
   * Leva o documento importado para outro cofre.
   *
   * Pede papel de editor nos dois cofres. O arquivo e o SHA-256 não mudam;
   * a mudança fica no rastro do cofre e na auditoria.
   *
   * `POST /v1/sign/imports/{id}/move`
   *
   * @param id ID do documento importado (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  moveSignImport(id: string, body: S.SignMoveBody, options?: RequestOptions): Promise<S.SignImportDto> {
    return this._http.request({ method: 'POST', path: `/v1/sign/imports/${seg(id)}/move`, body, options });
  }

  /**
   * Inclui uma pessoa, grupo, time ou unidade, ou troca o papel.
   *
   * Só administrador muda a lista; o cofre nunca fica sem uma pessoa
   * administradora (`sign_vault_last_admin`).
   *
   * `PUT /v1/sign/vaults/{id}/members`
   *
   * @param id ID do cofre (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  putSignVaultMember(id: string, body: S.SignVaultMemberBody, options?: RequestOptions): Promise<S.SignVaultDetailDto> {
    return this._http.request({ method: 'PUT', path: `/v1/sign/vaults/${seg(id)}/members`, body, options });
  }

  /**
   * Retira um sujeito da lista.
   *
   * Só administrador muda a lista; tirar a última pessoa administradora é
   * recusado (`sign_vault_last_admin`).
   *
   * `DELETE /v1/sign/vaults/{id}/members/{kind}/{subject_id}`
   *
   * @param id ID do cofre (Snowflake)
   * @param kind member, group, team ou unit
   * @param subjectId ID do sujeito (Snowflake)
   * @param options Per-call overrides.
   */
  removeSignVaultMember(id: string, kind: string, subjectId: string, options?: RequestOptions): Promise<S.SignVaultDetailDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/sign/vaults/${seg(id)}/members/${seg(kind)}/${seg(subjectId)}`, options });
  }

  /**
   * Unidades, grupos e times para a lista de um cofre.
   *
   * Busca por nome dentro da organização, com a contagem de pessoas de cada
   * um; as pessoas vêm de `/v1/members/detailed`.
   *
   * `GET /v1/sign/vaults/audiences`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  searchSignVaultAudiences(query?: SignVaultsSearchSignVaultAudiencesQuery, options?: RequestOptions): Promise<S.SignVaultAudiencesDto> {
    return this._http.request({ method: 'GET', path: `/v1/sign/vaults/audiences`, query, options });
  }

  /**
   * Abre um cofre com o código do autenticador.
   *
   * O bilhete da resposta vai de volta no cabeçalho `X-Sign-Vault-Ticket` em
   * toda rota do Assinador; o mesmo bilhete abre vários cofres.
   *
   * `POST /v1/sign/vaults/{id}/unlock`
   *
   * @param id ID do cofre (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  unlockSignVault(id: string, body: S.SignVaultUnlockBody, options?: RequestOptions): Promise<S.SignVaultOpeningDto> {
    return this._http.request({ method: 'POST', path: `/v1/sign/vaults/${seg(id)}/unlock`, body, options });
  }

  /**
   * Ajusta nome, descrição, público e segundo fator.
   *
   * Ligar o segundo fator pede o código; desligar encerra as aberturas.
   *
   * `PUT /v1/sign/vaults/{id}`
   *
   * @param id ID do cofre (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateSignVault(id: string, body: S.SignVaultBody, options?: RequestOptions): Promise<S.SignVaultSavedDto> {
    return this._http.request({ method: 'PUT', path: `/v1/sign/vaults/${seg(id)}`, body, options });
  }
}

/** Routes tagged `sign`. */
